  } catch {
    mevcut = 'sistem'
  }
  bildir()
  return mevcut
}

export async function temaTercihiniAyarla(tercih: TemaTercihi): Promise<void> {
  mevcut = tercih
  bildir()
  try {
    await AsyncStorage.setItem(ANAHTAR, tercih)
  } catch {
  }
}

export function temaTercihi(): TemaTercihi {
  return mevcut
}

function abone(d: () => void) {
  dinleyiciler.add(d)
  return () => {
    dinleyiciler.delete(d)
  }
}

