            ))}
            {[0.25, 0.5, 0.75].map((o) => (
              <Line key={`x${o}`} x1={olcu.en * o} y1={0} x2={olcu.en * o} y2={olcu.boy} />
            ))}
          </G>
          {/* Mesafe halkalari. */}
          <G fill="none" stroke={renk.turuncu} strokeOpacity={0.18}>
            {[0.4, 0.7, 1].map((o) => (
