      expect(screen.getByText('8 kişi burada')).toBeTruthy()
    })""","""    await render(<MekanAramaEkrani />)
    await screen.findByText('Sahil Kafe')
    await listeyiAc()

    // 2026-09-06: sekmeler kalkti, TEK liste var. Kisi sayisi artik
